---@class FishingGoodsService
local FishingGoodsService = Class("FishingGoodsService")

function FishingGoodsService.new(from)
    local obj = FishingGoodsService.New()
    obj.luaDialog = from
    for k, v in pairs(from) do
        obj[k]=v
    end
    return obj
end

function FishingGoodsService:UpdateInfo()
    local t = FishingUtils.GetFishingPropsList(self.placeId)
    for k, v in pairs(t) do
        local go = self.OptipnIconGroup.transform:Find("IconNode"..k)
        self:FillFishingProp(go,v, self.placeId)
    end
end

function FishingGoodsService:OnClick()

end

function FishingGoodsService:ShowMe()
    self:UpdateInfo()
    CfUtils.PlayAnimator(self.Root, "FishingGoodsShow")
end

function FishingGoodsService:HideMe()
    CfUtils.PlayAnimator(self.Root, "Out")
end


--绘制钓鱼道具
function FishingGoodsService:FillFishingProp(go, id, placeId)
    if not go or not id then
        return
    end
    local type = GoodsUtils.GetIdType(id)
    local num
    local dojo = FishingUtils.GetFishingGoodsDojo(id)
    if dojo then
        if type == Constants.IDType.GoodsReel or type == Constants.IDType.GoodsFishingRod then
            local vo = FishingUtils.GetFishingGoodsVoById(id)
            if vo then
                local str = checkNumber(dojo.durability)
                if checkNumber(dojo.durability) <= 0 then
                    str = "<color=#FF4040>"..str.."</color>"
                end
                num = str.."/"..checkNumber(vo.durability)
            end
        elseif type == Constants.IDType.GoodsBait or type == Constants.IDType.GoodsFishingLine then
            local str = checkNumber(dojo.num)
            if checkNumber(dojo.num) <= 0 then
                str = "<color=#FF4040>"..str.."</color>"
            end
            num = "x"..str
        end
    else
        num = "x<color=#FF4040>0</color>"
    end

    --local isBase = FishingUtils.IsBaseProps(id)
    --KTool.SetActive(go.transform:Find("ImgUnlimited"), false)-- isBase)


    local goodNode = go.transform:Find("GoodNode")
    ---@type GoodNodeMB
    local env = CfUtils.GetLuaScr(goodNode, 'Game.Behaviours.GoodNodeMB')
    if env then
        --KTool.SetActive(env.LvBg.gameObject, true)
    end
    CfUtils.RefeshGoodGo(goodNode, id, num, 0.55, nil, function()
        if FishingUtils.IsAutoing() then
            return
        end

        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFishPoolStoreBackPackPopupDialog, parameters = {selectType = type, fishPlaceId = placeId}}, {
            {id = Constants.UITypeIds.UIFishPoolGoFishingDialog}
        })
    end)
    KTool.SetActive(go, true)
end

return FishingGoodsService